# --- 토지이음 개별공시지가 API 주소 보정 ---
def _get_eum_official_price(opener, pnu):
    from urllib.parse import urlencode
    from urllib.request import Request
    import xml.etree.ElementTree as ET

    params = {
        "adm_sect_cd": pnu[:5],
        "land_loc_cd": pnu[5:10],
        "ledg_gbn": pnu[10:11],
        "bobn": pnu[11:15],
        "bubn": pnu[15:19],
    }
    query = "|".join(f"{key}={value}" for key, value in params.items())
    url = (
        "https://api.eum.go.kr/web/api/korep/UrlConnector.jsp?"
        + urlencode({"url": query})
    )
    request = Request(url, headers={
        "User-Agent": "Mozilla/5.0",
        "Referer": "https://www.eum.go.kr/web/ar/lu/luLandDet.jsp",
    })

    try:
        with opener.open(request, timeout=25) as response:
            root = ET.fromstring(response.read())

        if root.findtext("./HEADER/CODE", "").strip() != "0000":
            print("[공시지가] 조회 실패:", root.findtext("./HEADER/MESSAGE", ""))
            return ""

        price = root.findtext("./BODY/DECSN_JIGA/JIGA", "").strip()
        year = root.findtext("./BODY/DECSN_JIGA/BASE_YEAR", "").strip()
        month = root.findtext("./BODY/DECSN_JIGA/STDMT", "").strip()

        if not price:
            print("[공시지가] 응답에 금액이 없습니다.")
            return ""

        amount = f"{int(price.replace(',', '')):,}원"
        if year and month:
            amount += f" ({year}/{month.zfill(2)})"
        return amount

    except Exception as error:
        print("[공시지가] 조회 오류:", error)
        return ""


if lookup_api is not None:
    lookup_api.get_official_price = _get_eum_official_price
